diff --git a/js/packages/sdk/src/host-control/client.ts b/js/packages/sdk/src/host-control/client.ts
new file mode 100644
index 00000000..02beb9eb
--- /dev/null
+++ b/js/packages/sdk/src/host-control/client.ts
@@ -0,0 +1,193 @@
+import type { HostCommandMap, HostEventMap, HostEventOf, HostPlugin, PayloadOf, ResultOf } from "./plugin";
+import { corePlugin, isRecord } from "./plugin";
+import type { HostCommandRequest, HostFailure, HostResult } from "./protocol";
+import { HOST_CONTROL_PROTOCOL_VERSION, isWireErrorCode } from "./protocol";
+
+/** A computer whose Host Companion linked with this VitaDeck, as listed on the Shell Host Control Screen. */
+export type LinkedHost = { id: string; name: string; url: string };
+
+export type HostTransport = (
+  url: string,
+  init: { method: "POST"; headers: Record<string, string>; body: string },
+) => Promise<{ status: number; text(): Promise<string> }>;
+
+export type HostClientOptions = {
+  /** The linked host to call, by id. Defaults to the most recently linked one. */
+  hostId?: string;
+  /** Calls this companion URL instead of a linked host. */
+  url?: string;
+  transport?: HostTransport;
+  timeoutMs?: number;
+};
+
+type HostMethod<P, R extends object> = [P] extends [undefined]
+  ? () => Promise<HostResult<R>>
+  : (payload: P) => Promise<HostResult<R>>;
+
+export type HostClient<C extends HostCommandMap> = {
+  readonly [K in keyof C]: HostMethod<PayloadOf<C[K]>, ResultOf<C[K]>>;
+};
+
+const DEFAULT_TIMEOUT_MS = 5000;
+
+// Declared for the host in the runtime's runtime-native.d.ts; kept off the author-visible globals.
+const native = globalThis as unknown as { nativeGetHostControlLinks?: () => string };
+
+function isLinkedHost(value: unknown): value is LinkedHost {
+  return (
+    isRecord(value) && typeof value.id === "string" && typeof value.name === "string" && typeof value.url === "string"
+  );
+}
+
+/** The linked hosts, most recently linked first. Reads VitaDeck on every call, so a new link shows up at once. */
+export function linkedHosts(): LinkedHost[] {
+  const raw = native.nativeGetHostControlLinks?.() ?? "";
+  if (raw === "") return [];
+  try {
+    const parsed: unknown = JSON.parse(raw);
+    return Array.isArray(parsed) ? parsed.filter((item) => isLinkedHost(item)) : [];
+  } catch {
+    return [];
+  }
+}
+
+function failure(code: HostFailure["code"], message: string): HostFailure {
+  return { ok: false, code, message };
+}
+
+function resolveUrl(options: HostClientOptions): string | HostFailure {
+  if (options.url !== undefined) return options.url;
+  const hosts = linkedHosts();
+  const target = options.hostId === undefined ? hosts[0] : hosts.find((host) => host.id === options.hostId);
+  if (target) return target.url;
+  return failure(
+    "not_linked",
+    options.hostId === undefined
+      ? "No computer is linked. Link one from Host Control in the VitaDeck Shell."
+      : "That computer is no longer linked.",
+  );
+}
+
+function parseResult(text: string): HostResult<object> {
+  let parsed: unknown;
+  try {
+    parsed = JSON.parse(text);
+  } catch {
+    return failure("bad_response", "The Host Companion did not answer with JSON.");
+  }
+  if (!isRecord(parsed) || typeof parsed.ok !== "boolean") {
+    return failure("bad_response", "The Host Companion answered without an ok field.");
+  }
+  if (parsed.ok) return parsed as { ok: true };
+  const message = typeof parsed.message === "string" ? parsed.message : "The command failed.";
+  return failure(isWireErrorCode(parsed.code) ? parsed.code : "command_failed", message);
+}
+
+const defaultTransport: HostTransport = (url, init) => fetch(url, init);
+
+async function send(
+  plugin: string,
+  command: string,
+  payload: unknown,
+  options: HostClientOptions,
+): Promise<HostResult<object>> {
+  const url = resolveUrl(options);
+  if (typeof url !== "string") return url;
+
+  const request: HostCommandRequest = { protocolVersion: HOST_CONTROL_PROTOCOL_VERSION, plugin, command, payload };
+  const transport = options.transport ?? defaultTransport;
+  const timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS;
+
+  // The Vita fetch has no AbortSignal, so a timed-out command may still run on the computer. Never retried.
+  let timer: ReturnType<typeof setTimeout> | undefined;
+  const timeout = new Promise<HostFailure>((resolve) => {
+    timer = setTimeout(() => {
+      resolve(failure("timeout", `The Host Companion did not answer within ${timeoutMs} ms.`));
+    }, timeoutMs);
+  });
+  const exchange = (async (): Promise<HostResult<object>> => {
+    try {
+      const response = await transport(`${url.endsWith("/") ? url : `${url}/`}command`, {
+        method: "POST",
+        headers: { "Content-Type": "application/json" },
+        body: JSON.stringify(request),
+      });
+      return parseResult(await response.text());
+    } catch (error) {
+      return failure("unreachable", `Could not reach the Host Companion: ${String(error)}`);
+    }
+  })();
+
+  try {
+    return await Promise.race([exchange, timeout]);
+  } finally {
+    clearTimeout(timer);
+  }
+}
+
+/**
+ * A typed client for one Host Control Plugin. Every method resolves to a `HostResult` and never rejects for a
+ * Host Control failure. Without `hostId` or `url` it calls the most recently linked host, read at call time.
+ */
+export function createHostClient<C extends HostCommandMap>(
+  plugin: HostPlugin<C>,
+  options: HostClientOptions = {},
+): HostClient<C> {
+  const methods: Record<string, (payload?: unknown) => Promise<HostResult<object>>> = {};
+  for (const name of Object.keys(plugin.commands)) {
+    methods[name] = (payload) => send(plugin.id, name, payload, options);
+  }
+  return methods as HostClient<C>;
+}
+
+export type WatchHostEventsOptions = Omit<HostClientOptions, "timeoutMs"> & {
+  /** Called for each failed wait, before the next try: 5 s later, or 30 s after a `timeout`. */
+  onFailure?: (failure: HostFailure) => void;
+};
+
+// The companion holds an event wait for 25 s; the Vita's native fetch gives up at 30 s.
+const EVENT_WAIT_TIMEOUT_MS = 29_000;
+const EVENT_RETRY_MS = 5000;
+// A timed-out fetch keeps running natively for up to 30 s, so a computer that stopped answering is retried no faster.
+const EVENT_TIMEOUT_RETRY_MS = 30_000;
+
+/**
+ * Calls `onEvent` for every event the plugin emits on a linked computer from now on, within about one network
+ * round trip. Keeps one request waiting at the companion at a time. Returns a function that stops watching.
+ * A throw from `onEvent` or `onFailure` stops watching and fails the Deck App like any unhandled error.
+ */
+export function watchHostEvents<C extends HostCommandMap, E extends HostEventMap>(
+  plugin: HostPlugin<C, E>,
+  onEvent: (event: HostEventOf<E>) => void,
+  options: WatchHostEventsOptions = {},
+): () => void {
+  const { onFailure, ...clientOptions } = options;
+  const core = createHostClient(corePlugin, { ...clientOptions, timeoutMs: EVENT_WAIT_TIMEOUT_MS });
+  let stopped = false;
+  let after: number | undefined;
+  let timer: ReturnType<typeof setTimeout> | undefined;
+
+  const wait = async () => {
+    const batch = await core.events(after === undefined ? { plugin: plugin.id } : { plugin: plugin.id, after });
+    if (stopped) return;
+    if (batch.ok) {
+      after = batch.next;
+      // The companion only sends events of this plugin, which emits only the events its registry declares.
+      for (const event of batch.events) {
+        if (stopped) return;
+        onEvent(event as HostEventOf<E>);
+      }
+    } else {
+      onFailure?.(batch);
+    }
+    // `onFailure` may have stopped watching.
+    if (stopped) return;
+    const delay = batch.ok ? 0 : batch.code === "timeout" ? EVENT_TIMEOUT_RETRY_MS : EVENT_RETRY_MS;
+    timer = setTimeout(() => void wait(), delay);
+  };
+  void wait();
+  return () => {
+    stopped = true;
+    clearTimeout(timer);
+  };
+}

diff --git a/js/packages/sdk/src/host-control/plugin.ts b/js/packages/sdk/src/host-control/plugin.ts
new file mode 100644
index 00000000..1050df95
--- /dev/null
+++ b/js/packages/sdk/src/host-control/plugin.ts
@@ -0,0 +1,171 @@
+import type { HostControlWireErrorCode } from "./protocol";
+
+declare const resultType: unique symbol;
+declare const dataType: unique symbol;
+
+/**
+ * One Host Control command: a guard the Host Companion runs on the payload, and a result type that exists only
+ * for TypeScript. There is no schema library, since it would ship inside every Deck App bundle.
+ */
+export type HostCommand<P, R extends object> = {
+  readonly isPayload: (value: unknown) => value is P;
+  readonly [resultType]?: R;
+};
+
+export type HostCommandMap = Record<string, HostCommand<unknown, object>>;
+
+/** One **Host Control Event** a plugin's implementation emits; its data type exists only for TypeScript. */
+export type HostEvent<D> = { readonly [dataType]?: D };
+
+export type HostEventMap = Record<string, HostEvent<unknown>>;
+
+/**
+ * A **Host Control Plugin**: the commands a Deck App imports to call a computer and the events it can watch,
+ * which the Host Companion loads an implementation for. `id` namespaces both on the wire.
+ */
+export type HostPlugin<C extends HostCommandMap = HostCommandMap, E extends HostEventMap = HostEventMap> = {
+  readonly id: string;
+  readonly commands: C;
+  readonly events: E;
+};
+
+export type PayloadOf<T> = T extends HostCommand<infer P, object> ? P : never;
+export type ResultOf<T> = T extends HostCommand<unknown, infer R> ? R : never;
+export type DataOf<T> = T extends HostEvent<infer D> ? D : never;
+
+/** An event as `watchHostEvents` delivers it: `name` narrows `data`. */
+export type HostEventOf<E extends HostEventMap> = {
+  [K in keyof E & string]: { seq: number; name: K; data: DataOf<E[K]> };
+}[keyof E & string];
+
+export function command<P, R extends object>(isPayload: (value: unknown) => value is P): HostCommand<P, R> {
+  return { isPayload };
+}
+
+export function event<D>(): HostEvent<D> {
+  return {};
+}
+
+// A plugin without events has an empty event map, so `watchHostEvents` offers it no event names.
+// oxlint-disable-next-line typescript/no-generated-empty-object-type
+export function defineHostPlugin<const C extends HostCommandMap, const E extends HostEventMap = Record<never, never>>(
+  id: string,
+  commands: C,
+  events?: E,
+): HostPlugin<C, E> {
+  return { id, commands, events: events ?? ({} as E) };
+}
+
+/** Guard for commands that take no payload. */
+export function isAbsent(value: unknown): value is undefined {
+  return value === undefined;
+}
+
+export function isRecord(value: unknown): value is Record<string, unknown> {
+  return typeof value === "object" && value !== null && !Array.isArray(value);
+}
+
+export type HostCapabilities = {
+  protocolVersion: number;
+  name: string;
+  platform: string;
+  /** Plugins the companion loaded. It may list plugins and commands this Deck App does not know. */
+  plugins: { id: string; commands: string[] }[];
+};
+
+/** Events a plugin emitted after `after`, and the sequence number to pass as `after` next time. */
+export type HostEventBatch = { events: { seq: number; name: string; data: unknown }[]; next: number };
+
+const hasText = (value: unknown): value is { text: string } => isRecord(value) && typeof value.text === "string";
+
+/**
+ * Always loaded by every Host Companion. `events` waits up to 25 s for a plugin's events, which is how events
+ * reach the Vita (see `watchHostEvents`); `notify` emits a `notice`, which `vitadeck-host-companion notify` sends.
+ */
+export const corePlugin = defineHostPlugin(
+  "core",
+  {
+    capabilities: command<undefined, HostCapabilities>(isAbsent),
+    echo: command<{ text: string }, { text: string }>(hasText),
+    events: command<{ plugin: string; after?: number }, HostEventBatch>(
+      (value): value is { plugin: string; after?: number } =>
+        isRecord(value) &&
+        typeof value.plugin === "string" &&
+        (value.after === undefined || (Number.isSafeInteger(value.after) && Number(value.after) >= 0)),
+    ),
+    notify: command<{ text: string }, object>(hasText),
+  },
+  { notice: event<{ text: string }>() },
+);
+
+export const HOST_PLUGIN_SCHEMA_VERSION = 1;
+
+/**
+ * `manifest.json` of a Host Plugin Package, the `<slug>.vdplugin` folder `vitadeck build` writes. `entry` is the
+ * bundled implementation; the package may hold other files next to it, which the code finds through
+ * `import.meta.url`.
+ */
+export type HostPluginManifest = {
+  schemaVersion: typeof HOST_PLUGIN_SCHEMA_VERSION;
+  name: string;
+  version: string;
+  entry: string;
+};
+
+export type HostPluginImplementations<C extends HostCommandMap> = {
+  readonly [K in keyof C]: (payload: PayloadOf<C[K]>) => Promise<ResultOf<C[K]>> | ResultOf<C[K]>;
+};
+
+/**
+ * A Host Control Plugin with its implementation, as a Host Plugin Package's entry default-exports it. The Host
+ * Companion checks this shape rather than a class, since every package bundles its own copy of this module.
+ */
+export type ImplementedHostPlugin = {
+  readonly id: string;
+  readonly commands: ReadonlyMap<string, ImplementedHostCommand>;
+  readonly start?: (emit: (name: string, data: unknown) => void) => (() => void) | void;
+};
+
+export type HostPluginEmit<E extends HostEventMap> = <K extends keyof E & string>(name: K, data: DataOf<E[K]>) => void;
+
+/** Started when the companion loads the plugin; the returned function runs when it unloads or reloads. */
+export type HostPluginLifecycle<E extends HostEventMap> = {
+  start(emit: HostPluginEmit<E>): (() => void) | void;
+};
+
+type ImplementedHostCommand = {
+  readonly isPayload: (value: unknown) => boolean;
+  readonly run: (payload: unknown) => Promise<object> | object;
+};
+
+/** Thrown by an implementation to fail with a specific wire code. Any other throw answers `command_failed`. */
+export class HostCommandError extends Error {
+  readonly code: HostControlWireErrorCode;
+
+  constructor(code: HostControlWireErrorCode, message: string) {
+    super(message);
+    this.name = "HostCommandError";
+    this.code = code;
+  }
+}
+
+/** The computer side of a plugin: the default export of the file `hostPlugin` names in `vitadeck.config.json`. */
+export function implementHostPlugin<const C extends HostCommandMap, const E extends HostEventMap>(
+  plugin: HostPlugin<C, E>,
+  implementations: HostPluginImplementations<C>,
+  lifecycle?: HostPluginLifecycle<E>,
+): ImplementedHostPlugin {
+  // The companion runs the guard first, so each implementation only sees its own payload type.
+  const runs = implementations as unknown as Record<
+    string,
+    ((payload: unknown) => object | Promise<object>) | undefined
+  >;
+  const commands = new Map<string, ImplementedHostCommand>();
+  for (const [name, definition] of Object.entries(plugin.commands)) {
+    const run = runs[name];
+    if (typeof run !== "function") throw new Error(`Plugin ${plugin.id} has no implementation for ${name}.`);
+    commands.set(name, { isPayload: (value) => definition.isPayload(value), run });
+  }
+  if (!lifecycle) return { id: plugin.id, commands };
+  return { id: plugin.id, commands, start: (emit) => lifecycle.start(emit) };
+}

diff --git a/js/packages/sdk/src/host-control/protocol.ts b/js/packages/sdk/src/host-control/protocol.ts
new file mode 100644
index 00000000..daf0a2d5
--- /dev/null
+++ b/js/packages/sdk/src/host-control/protocol.ts
@@ -0,0 +1,50 @@
+/** Bumped only by a breaking change to the Host Control wire contract. */
+export const HOST_CONTROL_PROTOCOL_VERSION = 1;
+
+/** Codes a Host Companion or the VitaDeck link endpoint answers with, each with a fixed HTTP status. */
+export const HOST_CONTROL_WIRE_ERRORS = {
+  malformed_request: 400,
+  unsupported_protocol_version: 400,
+  forbidden: 403,
+  unknown_plugin: 404,
+  unknown_command: 404,
+  unknown_link: 404,
+  payload_too_large: 413,
+  invalid_payload: 422,
+  command_failed: 500,
+  unsupported_platform: 501,
+} as const;
+
+export type HostControlWireErrorCode = keyof typeof HOST_CONTROL_WIRE_ERRORS;
+
+/** Codes only the Deck App side produces; no companion sends them. */
+export type HostControlClientErrorCode = "not_linked" | "unreachable" | "timeout" | "bad_response";
+
+export type HostControlErrorCode = HostControlWireErrorCode | HostControlClientErrorCode;
+
+export type HostFailure = { ok: false; code: HostControlErrorCode; message: string };
+
+/** The Runtime Upload POST result shape: `ok: true` plus the command's fields, or a coded failure. */
+export type HostResult<R extends object> = ({ ok: true } & R) | HostFailure;
+
+/** `POST {companion url}command`, Vita to companion. `payload` is omitted for commands that take none. */
+export type HostCommandRequest = {
+  protocolVersion: number;
+  plugin: string;
+  command: string;
+  payload?: unknown;
+};
+
+/** `POST http://{vita}:{port}/link`, companion to Vita. `id` stays the same across relinks of one companion. */
+export type HostControlLinkRequest = {
+  protocolVersion: number;
+  id: string;
+  name: string;
+  url: string;
+  /** Update this id's existing link only; VitaDeck answers 404 `unknown_link` when it has none, e.g. after the user forgot it. */
+  relink?: boolean;
+};
+
+export function isWireErrorCode(code: unknown): code is HostControlWireErrorCode {
+  return typeof code === "string" && Object.hasOwn(HOST_CONTROL_WIRE_ERRORS, code);
+}

